	@ParameterizedTest
	@ValueSource(ints = { 32, 63, 64, 65, 127, 128, 257 })
	void preservesCanonicalRecordsAcrossShortReadsAndEveryLineEnding(int blockBytes) throws Exception {
		// The first CR is the last byte of the first buffer, so its LF arrives in the next read.
		StringBuilder document = new StringBuilder("\uFEFF#" + "x".repeat(blockBytes - 5) + "\r\n");
		document.append("VERSION \"1.2\"\r");
		List<List<Value>> expected = new ArrayList<>();
		var values = SimpleValueFactory.getInstance();
		var predicate = values.createIRI("urn:p");
		var context = values.createIRI("urn:g");
		for (int index = 0; index < 24; index++) {
			String label = index == 7 ? "x".repeat(blockBytes * 3 + 7) + "é👋" : "value-" + index;
			document.append("<urn:s")
					.append(index)
					.append("> <urn:p> \"")
					.append(label)
					.append("\" <urn:g> .");
			if (index != 23) {
				document.append(switch (index % 3) {
				case 0 -> "\r\n";
				case 1 -> "\r";
				default -> "\n";
				});
			}
			expected.add(List.of(values.createIRI("urn:s" + index), predicate, values.createLiteral(label), context));
		}
		CanonicalStagedInput staged = stage(document.toString(), blockBytes);
		Map<Long, Value[]> components = new TreeMap<>();
		Map<Value, Integer> actualRoles = new HashMap<>();
		for (int partition = 0; partition < PARTITIONS; partition++) {
			int currentPartition = partition;
			BulkLz4.readConcatenated(staged.componentPath(partition), staged.componentCodec(), input -> {
				long previousOrdinal = -1L;
				int previousComponent = -1;
				while (true) {
					long ordinal;
					try {
						ordinal = input.readLong();
					} catch (EOFException end) {
						return;
					}
					int component = input.readUnsignedByte();
					byte[] key = new byte[input.readInt()];
					input.readFully(key);
					assertThat(ordinal > previousOrdinal || ordinal == previousOrdinal && component > previousComponent)
							.isTrue();
					assertThat((int) CanonicalTermCodec.routeHash64(key) & (PARTITIONS - 1))
							.isEqualTo(currentPartition);
					Value value = CanonicalTermCodec.decode(key);
					assertThat(key).isEqualTo(CanonicalTermCodec.encode(value));
					Value[] statement = components.computeIfAbsent(ordinal, ignored -> new Value[4]);
					assertThat(statement[component]).isNull();
					statement[component] = value;
					previousOrdinal = ordinal;
					previousComponent = component;
				}
			});
			staged.forEachPartitionValue(partition, (bucket, hash, roles, key) -> {
				assertThat(hash).isEqualTo(CanonicalTermCodec.routeHash64(key));
				actualRoles.merge(CanonicalTermCodec.decode(key), roles, (left, right) -> left | right);
			});
		}
		assertThat(staged.statements()).isEqualTo(expected.size());
		assertThat(staged.componentRecords()).isEqualTo(4L * expected.size());
		assertThat(components.values().stream().map(List::of).toList()).isEqualTo(expected);
		Map<Value, Integer> expectedRoles = new HashMap<>();
		for (List<Value> statement : expected) {
			for (int component = 0; component < 4; component++) {
				expectedRoles.merge(statement.get(component), 1 << component, (left, right) -> left | right);
			}
		}
		assertThat(actualRoles).isEqualTo(expectedRoles);
		Map<Value, Long> predicateCounts = new HashMap<>();
		staged.forEachPredicateCount((key, count) -> predicateCounts.put(CanonicalTermCodec.decode(key), count));
		assertThat(predicateCounts).containsExactly(Map.entry(predicate, 24L));
	}

	@ParameterizedTest
	@ValueSource(ints = { 32, 63, 64, 65, 127, 128, 257 })
	void reportsAbsoluteLineAfterSplitCrLfAndLongLines(int blockBytes) {
		String input = "#" + "x".repeat(blockBytes - 2) + "\r\n"
				+ "\r\n#" + "x".repeat(blockBytes * 3 + 1) + "\r"
				+ "<urn:s> <urn:p> <urn:o> .\n"
				+ "<urn:s> <urn:p> broken .";
		RDFParseException failure = assertThrows(RDFParseException.class, () -> stage(input, blockBytes));
		assertThat(failure.getLineNumber()).isEqualTo(5L);
		assertThat(failure.getColumnNumber()).isEqualTo(17L);
		assertThat(failure.getMessage())
				.isEqualTo("Expected IRI, blank node, literal, or triple term [line 5, column 17]");
	}

	@Test
	void rejectsBomAtTheStartOfALaterBlock() {
		int blockBytes = 64;
		String input = "#" + "x".repeat(blockBytes - 2) + "\n\uFEFF<urn:s> <urn:p> <urn:o> .\n";
		RDFParseException failure = assertThrows(RDFParseException.class, () -> stage(input, blockBytes));
		assertThat(failure.getLineNumber()).isEqualTo(2L);
		assertThat(failure.getColumnNumber()).isEqualTo(1L);
		assertThat(failure.getMessage()).isEqualTo("Expected IRI or blank node subject [line 2, column 1]");
	}

	@Test
	void resetsBomAndBlankNodeScopeAfterEmptyAndUnterminatedInputs() throws Exception {
		CanonicalStagedInput staged = stage(List.of(
				input("\uFEFF#first\r\n_:node <urn:p> <urn:o> .", RDFFormat.NTRIPLES, 0),
				input("", RDFFormat.NQUADS, 1),
				input("\uFEFFVERSION \"1.2\"\r\n_:node <urn:p> <urn:o> <urn:g> .\r", RDFFormat.NQUADS, 2)),
				32, new AtomicBoolean());
		List<String> blankNodes = new ArrayList<>();
		for (int partition = 0; partition < PARTITIONS; partition++) {
			staged.forEachPartitionValue(partition, (bucket, hash, roles, key) -> {
				if (CanonicalTermCodec.decode(key) instanceof BNode blankNode) {
					blankNodes.add(blankNode.getID());
				}
			});
		}
		assertThat(staged.statements()).isEqualTo(2L);
		assertThat(blankNodes).containsExactlyInAnyOrder("f0/node", "f2/node");
	}

